import{_ as i,W as d,s as h,u,ah as e,I as a,w as t,Z as p,A as s}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const k=JSON.parse('{"title":"修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误 | LCTT x X-CMD","titleTemplate":false,"description":"修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220714 Fixing -Command -python- not found- Error in Ubuntu Linux","title":"修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误","tag":"202207"},"relativePath":"202207/20220714 Fixing -Command -python- not found- Error in Ubuntu Linux.md","filePath":"[post].md"}'),l={name:"202207/20220714 Fixing -Command -python- not found- Error in Ubuntu Linux.md"};function y(c,n,r,b,m,g){const o=d("Link");return u(),h("div",null,[n[18]||(n[18]=e(`<h1 id="修复-ubuntu-linux-中-command-python-not-found-的错误" tabindex="-1">修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误 <a class="header-anchor" href="#修复-ubuntu-linux-中-command-python-not-found-的错误" aria-label="Permalink to 修复 Ubuntu Linux 中 “Command ‘python’ not found” 的错误">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/30/071627r176w1k1y5dkkw6w.jpg" alt=""></p><p>如何在 Linux 终端中运行一个 Python 程序？像这样，对吗？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python program.py</span></span></code></pre></div><p>然而，如果你试图在 Ubuntu（和其他一些发行版）中使用 <code>python</code> 命令，它会抛出一个错误。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command ‘python’ not found, did you mean:</span></span>
<span class="line"><span>command ‘python3’ from deb python3</span></span>
<span class="line"><span>command ‘python’ from deb python-is-python3</span></span></code></pre></div><p>如果你注意这个错误信息，它说明了很多东西。<strong>这里的 <code>python</code> 命令实际上是 <code>python3</code></strong>。</p><p>如果你不理解，不用担心。我将在这里详细解释。</p><h3 id="为什么在-ubuntu-上没有发现-python-命令" tabindex="-1">为什么在 Ubuntu 上没有发现 python 命令？ <a class="header-anchor" href="#为什么在-ubuntu-上没有发现-python-命令" aria-label="Permalink to 为什么在 Ubuntu 上没有发现 python 命令？">​</a></h3><p>这是因为 Python 语言不是以 <code>python</code> 的形式安装的，而是以 <code>python3</code> 或 <code>python2</code> 的形式安装的（在一些老的 Ubuntu 版本中）。</p><p>在遥远的过去的某个时间点，Python 实际上是作为 <code>python</code> 包/可执行文件提供的。当 Python 发布第二版时，Ubuntu 和其他发行版不得不同时支持 Python 1.x 和 2.x 版本。</p><p>因此，他们将较新的 Python 版本命名为 <code>python2</code>，以区分这两个版本。其他应用或库也在其代码中指定 <code>python</code> 或 <code>python2</code>。</p><p>最终，Python 1 版本被完全停用，但软件包继续被命名为 <code>python2</code>。</p><p>类似地，当 Python 3 版本发布时，发行版开始同时提供 <code>python2</code> 和 <code>python3</code> 包。</p><p>Python 2 不再被支持，Python 3.x 是你在 Ubuntu 上安装的版本。该软件包仍被命名为 <code>python3</code>。</p><p><strong>总结一下，你已经在 Ubuntu 上安装了 Python。它是以 <code>python3</code> 软件包方式使用的。</strong></p>`,16)),a("p",null,[n[1]||(n[1]=t("那么，当你 ")),p(o,{href:"https://itsfoss.com/bash-command-not-found/"},{default:s(()=>n[0]||(n[0]=[t("在 Ubuntu 上看到 “Python command not found” 的错误")])),_:1}),n[2]||(n[2]=t(" 时，你有什么选择？让我来介绍一下。"))]),n[19]||(n[19]=e(`<h3 id="确保你的系统中已经安装了-python" tabindex="-1">确保你的系统中已经安装了 Python <a class="header-anchor" href="#确保你的系统中已经安装了-python" aria-label="Permalink to 确保你的系统中已经安装了 Python">​</a></h3><p>它应该已经安装了，但仔细检查一下也无妨。</p><p>Ubuntu 18.04 也有 Python 2，但 20.04 及更高版本只有 Python 3。不过，你有哪个版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type python python2 python3</span></span></code></pre></div><p>正如你在下面的截图中看到的，我的系统上安装了 Python 3 版本。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/check-python-version-ubuntu.png" alt="Checking Python version in Ubuntu"></p><p>如果你没有安装任何 Python 版本，你可以用以下命令安装 Python 3 版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install python3</span></span></code></pre></div><h3 id="使用-python3-而不是-python" tabindex="-1">使用 python3 而不是 python <a class="header-anchor" href="#使用-python3-而不是-python" aria-label="Permalink to 使用 python3 而不是 python">​</a></h3><p>如果对你来说不是太麻烦，在需要的地方使用 <code>python3</code> 命令而不是 <code>python</code>。</p><p>想检查已安装的 Python 版本吗？请这样输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 --version</span></span></code></pre></div><p>然后你会在输出中得到版本的详细信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~$ python3 --version</span></span>
<span class="line"><span>Python 3.10.4</span></span></code></pre></div><p>如果你必须运行一个 Python 程序，请像这样执行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 program.py</span></span></code></pre></div><p>这在大多数情况下应该对你有用。但是，如果你使用的是一些（旧的）Python 应用，期望在其代码中运行 Python 可执行文件，你就会有问题。别担心，你也可以绕过它。</p><h3 id="将-python3-链接为-python" tabindex="-1">将 python3 链接为 python <a class="header-anchor" href="#将-python3-链接为-python" aria-label="Permalink to 将 python3 链接为 python">​</a></h3><p>你可以在你的 <code>.bashrc</code> 文件中创建一个永久别名，像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alias python=&#39;python3&#39;</span></span></code></pre></div><p>这样，你可以运行 <code>python</code> 命令，而你的系统运行 <code>python3</code>。</p><p>这在大多数情况下都会起作用，除非某些程序期望运行 <code>/usr/bin/python</code>。现在，你可以在 <code>/usr/bin/python</code> 和 <code>/usr/bin/python3</code> 之间建立符号链接，但对于 Ubuntu 用户来说，存在一个更简单的选择。</p><p>对于 Ubuntu 20.04 和更高版本，如果你安装了 <code>python-is-python3</code> 软件包，你有一个软件包可以自动完成所有链接创建。这也是原始错误信息所提示的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install python-is-python3</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/install-python-is-python3-ubuntu.png" alt="install python is python3 ubuntu"></p><p>你可以看到符号链接已经被创建，你可以使用 <code>python</code> 命令（实际上是运行 <code>python3</code>），没有任何问题。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/checking-python-ubuntu.png" alt="checking python ubuntu"></p><p>我希望这能澄清 Ubuntu 中 Python 软件包的问题。如果你有任何问题或建议，请告诉我。</p><hr>`,29)),a("p",null,[n[4]||(n[4]=t("via: ")),p(o,{href:"https://itsfoss.com/python-not-found-ubuntu/"},{default:s(()=>n[3]||(n[3]=[t("https://itsfoss.com/python-not-found-ubuntu/")])),_:1})]),a("p",null,[n[9]||(n[9]=t("作者：")),p(o,{href:"https://itsfoss.com/author/abhishek/"},{default:s(()=>n[5]||(n[5]=[t("Abhishek Prakash")])),_:1}),n[10]||(n[10]=t(" 选题：")),p(o,{href:"https://github.com/lkxed"},{default:s(()=>n[6]||(n[6]=[t("lkxed")])),_:1}),n[11]||(n[11]=t(" 译者：")),p(o,{href:"https://github.com/geekpi"},{default:s(()=>n[7]||(n[7]=[t("geekpi")])),_:1}),n[12]||(n[12]=t(" 校对：")),p(o,{href:"https://github.com/wxy"},{default:s(()=>n[8]||(n[8]=[t("wxy")])),_:1})]),a("p",null,[n[15]||(n[15]=t("本文由 ")),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>n[13]||(n[13]=[t("LCTT")])),_:1}),n[16]||(n[16]=t(" 原创编译，")),p(o,{href:"https://linux.cn/"},{default:s(()=>n[14]||(n[14]=[t("Linux中国")])),_:1}),n[17]||(n[17]=t(" 荣誉推出"))])])}const x=i(l,[["render",y]]);export{k as __pageData,x as default};
